mapper.update:
UPDATE YX_LEASE_ITEM_CLASSIFY t
SET t.ADVANCED_EQUIPMENT_FLAG = #{advancedEquipmentFlag}
WHERE
    t.CLASSIFY_ID = #{classifyId}
   OR t.SUPERIOR_CLASSIFY_ID = #{classifyId}

mapper.select:
select v.* from (select t.classify_id, t.classify_code, t.label, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'LEASE_ITEM_LABEL' and sv.code_value = t.label) label_n, t.attribute, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'LEASE_ITEM_ATTRIBUTE' and sv.code_value = t.attribute) attribute_n, t.attribute_value, t.superior_classify_id, (select ic.attribute_value from yx_lease_item_classify ic where ic.classify_id = t.superior_classify_id) superior_classify_id_n, t.manufacturer_id, (select m.manufacturer_name from yx_lease_item_manufacturer m where m.manufacturer_id = t.manufacturer_id) manufacturer_id_n, t.advanced_equipment_flag, t.enabled_flag, to_char(t.creation_date, 'yyyy-mm-dd') create_date, t.created_by create_user_id, (select su.description from sys_user su where su.user_id = t.created_by) create_user_id_n, case when t.classify_id in (select ic.classify_id from yx_lease_item_classify ic start with ic.classify_id = nvl(#{classifyId},-1) connect by ic.classify_id = prior ic.superior_classify_id) then 'Y' else 'N' end expand_flag, (select wm_concat(ic.classify_id) from yx_lease_item_classify ic start with ic.classify_id = t.classify_id connect by ic.classify_id = prior ic.superior_classify_id) seq_num, t.last_update_date, t.last_updated_by from yx_lease_item_classify t) v
and v.classify_code = #{classifyCode}
and v.label = #{label}
and v.attribute = #{attribute}
and v.attribute_value = #{attributeValue}
and v.superior_classify_id = #{superiorClassifyId}
and v.manufacturer_id = #{manufacturerId}
and v.manufacturer_id_n = #{manufacturerIdN}
and v.advanced_equipment_flag = #{advancedEquipmentFlag}
and v.enabled_flag = #{enabledFlag}
and to_date(v.create_date,'yyyy-mm-dd') >= to_date(#{createDateFrom},'yyyy-mm-dd')
and to_date(v.create_date,'yyyy-mm-dd') <= to_date(#{createDateTo},'yyyy-mm-dd')
and v.create_user_id = #{createUserId}
order by v.classify_code

select v.* from (select t.classify_id, t.classify_code, t.label, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'LEASE_ITEM_LABEL' and sv.code_value = t.label) label_n, t.attribute, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'LEASE_ITEM_ATTRIBUTE' and sv.code_value = t.attribute) attribute_n, t.attribute_value, t.superior_classify_id, (select ic.attribute_value from yx_lease_item_classify ic where ic.classify_id = t.superior_classify_id) superior_classify_id_n, t.manufacturer_id, (select m.manufacturer_name from yx_lease_item_manufacturer m where m.manufacturer_id = t.manufacturer_id) manufacturer_id_n, (select m.BP_ID from yx_lease_item_manufacturer m where m.manufacturer_id = t.manufacturer_id) BP_ID, t.advanced_equipment_flag, t.enabled_flag, to_char(t.creation_date, 'yyyy-mm-dd') create_date, t.created_by create_user_id, (select su.description from sys_user su where su.user_id = t.created_by) create_user_id_n, case when t.classify_id in (select ic.classify_id from yx_lease_item_classify ic start with ic.classify_id = nvl(#{classifyId},-1) connect by ic.classify_id = prior ic.superior_classify_id) then 'Y' else 'N' end expand_flag, (select wm_concat(ic.classify_id) from yx_lease_item_classify ic start with ic.classify_id = t.classify_id connect by ic.classify_id = prior ic.superior_classify_id) seq_num, t.last_update_date, t.last_updated_by, t.durable_years, t.residuals_rate from yx_lease_item_classify t) v
and ( /*非进件部门与管理公司*/ exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and (fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER' OR FA.POSITION_ID =(SELECT P.POSITION_ID FROM FND_ORG_POSITION P WHERE P.POSITION_CODE='MC0001'))) or /*用户关联合作方= 产品生产厂商关联合作方*/ ( SELECT case when t.BP_CATEGORY ='主机厂' and t.RELATION_TYPE='MANUFACTURER' then t.RELATED_BP_ID when t.BP_CATEGORY ='主机厂' and t.RELATION_TYPE !='MANUFACTURER' then null when t.BP_CATEGORY ='经销商' and t.RELATION_TYPE='MANUFACTURER' then t.RELATED_BP_ID when t.BP_CATEGORY ='经销商' and t.RELATION_TYPE !='MANUFACTURER' then up_RELATED_BP_ID else null end as RELATED_manufacture_ID FROM ( SELECT U1.BP_CATEGORY, hr.RELATION_TYPE, hr.RELATED_BP_ID, CASE WHEN hr.RELATION_TYPE = 'VENDER' THEN ( SELECT rr.RELATED_BP_ID FROM hls_bp_master_relation rr WHERE rr.bp_id = hr.RELATED_BP_ID AND rr.RELATION_TYPE = 'MANUFACTURER' and rr.ENABLED_FLAG = 'Y') ELSE NULL END AS up_RELATED_BP_ID FROM sys_user_allocation su1,SYS_USER u1, hls_bp_master_relation hr WHERE u1.USER_ID = su1.USER_ID AND hr.bp_id = u1.bp_id and hr.ENABLED_FLAG = 'Y' AND SU1.ENABLED_FLAG='Y' AND U1.USER_ID=#{createdBy} ) t )=v.BP_ID )
and v.classify_code like concat(concat('%',#{classifyCode}),'%')
and v.label = #{label}
and v.attribute = #{attribute}
and v.attribute_value like concat(concat('%',#{attributeValue}),'%')
and v.superior_classify_id = #{superiorClassifyId}
and v.manufacturer_id = #{manufacturerId}
and v.advanced_equipment_flag = #{advancedEquipmentFlag}
and v.enabled_flag = #{enabledFlag}
and to_date(v.create_date,'yyyy-mm-dd') >= to_date(#{createDateFrom},'yyyy-mm-dd')
and to_date(v.create_date,'yyyy-mm-dd') <= to_date(#{createDateTo},'yyyy-mm-dd')
and v.create_user_id = #{createUserId}
order by v.classify_code

select t.code_value
from sys_code_value_b_v t
where t.code = #{code}
  and t.meaning = #{codeName}

select count(*)
from yx_lease_item_classify ic
where ic.label = #{label}
  and ic.attribute = #{attribute}
  and ic.attribute_value = #{attributeValue}
  and ic.manufacturer_id = #{manufacturerId}
  and ic.superior_classify_id = #{superiorClassifyId}
  and ic.classify_id != nvl(#{classifyId},-1)
